const PAYLOAD = [{"id":"pnj-aseryns-terres-temples-laurie-d-sun-01","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Laurie D. Sun","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Laurie D. Sun","real_name_source":"Laurie D. Sun","nom_verite":"Darksun","nom_verite_source":"Lorinae Athegos (Darksun)","race":"Aseryne (paleo-atlante)","age":"«30 ans » - ??? ns","origine":"Américaine","statut":"Reine des Atlantes et des aseryns","affiliations":"Crawlers : Gunwatcher","source_group":"Atlantide","source_order":1,"source_page":9,"identity_keys":["Lorinae Athegos","Laurie D. Sun","Lorinae Athegos (Darksun)","Darksun"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Trône royal : Lorinae Athegos Nom de la Réalité : Laurie D. Sun Nom de la Vérité : Lorinae Athegos (Darksun) Age : «30 ans » - ??? ns Affiliations : Crawlers : Gunwatcher Nationalité d’origine : Américaine Ethnie réelle : Aseryne (paleo-atlante) Statut : Reine des Atlantes et des aseryns Laurie D. Sun possède un vaste réseau d’enquête, ce n’est pas une détective privée solitaire, elle est à la tête de la « Darksun association », une petite entreprise de renseignement possédant enquêteurs, espions et anciens commandos. Elle possède l’élite des « Gunwatchers » et les fixers ont plaisir à recourir à ses pro plus que des privés solitaires n’ayant pas la réputation d’une Silver par exemple. Autrefois membre d’un groupe d’aventuriers sur Aèr, dont fit partie l’ancienne reine elfe, Nysril Isildwind, elle reçut l’immense honneur et la tâche compliquée d’assurer la gouvernance que sa sœur avait hérité de son époux. Sacrée par Kalira Athegos, la reine de légende, elle fut, de fait, considérée comme sa fille adoptive et sa légitime héritière désignée. Les ducs ne protestèrent pas, mais l’arrivée en Atlantide ne fut pas simple, la belle aventurière découvrant des aseryns refusant l’autorité des « néo-atlantes ». Elle entama des négociations avec ls muliens et les autres, mais ils étaient fermés et hostiles. Certains ducs atlantes se montèrent même ouverts à reconnaitre Kyriak mais c’était sans compter sur le génie de l’ancienne aventurière, au caractère bien trempé. Elle sait qu’il lui sera long d’accomplir la réunification des Aseryns, mais elle s’astreint à tenter cette tâche colossale."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Laurie D. Sun"],["Âge apparent","30 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Trône royal : Lorinae Athegos"],["Nom de la Réalité","Laurie D. Sun"],["Nom de la Vérité","Lorinae Athegos (Darksun)"],["Âge source","«30 ans » - ??? ns"],["Affiliations","Crawlers : Gunwatcher"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (paleo-atlante)"],["Statut","Reine des Atlantes et des aseryns"]]},{"type":"p","style":"lore","text":"Laurie D. Sun possède un vaste réseau d’enquête, ce n’est pas une détective privée solitaire, elle est à la tête de la « Darksun association », une petite entreprise de renseignement possédant enquêteurs, espions et anciens commandos. Elle possède l’élite des « Gunwatchers » et les fixers ont plaisir à recourir à ses pro plus que des privés solitaires n’ayant pas la réputation d’une Silver par exemple. Autrefois membre d’un groupe d’aventuriers sur Aèr, dont fit partie l’ancienne reine elfe, Nysril Isildwind, elle reçut l’immense honneur et la tâche compliquée d’assurer la gouvernance que sa sœur avait hérité de son époux. Sacrée par Kalira Athegos, la reine de légende, elle fut, de fait, considérée comme sa fille adoptive et sa légitime héritière désignée. Les ducs ne protestèrent pas, mais l’arrivée en Atlantide ne fut pas simple, la belle aventurière découvrant des aseryns refusant l’autorité des « néo-atlantes ». Elle entama des négociations avec ls muliens et les autres, mais ils étaient fermés et hostiles. Certains ducs atlantes se montèrent même ouverts à reconnaitre Kyriak mais c’était sans compter sur le génie de l’ancienne aventurière, au caractère bien trempé. Elle sait qu’il lui sera long d’accomplir la réunification des Aseryns, mais elle s’astreint à tenter cette tâche colossale."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-leder-caendis-02","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Leder Caendis","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Leder Caendis","nom_verite_source":"Leder Caendis","race":"aseryne (paleo-atlante)","age":"« 70 ans » - ???? ans","origine":"atlante","statut":"duc","affiliations":"_","source_group":"Atlantide","source_order":2,"source_page":9,"identity_keys":["Leder Caendis"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Valatar: Leder Caendis Nom de la Réalité : _ Nom de la Vérité : Leder Caendis Age : « 70 ans » - ???? ans Affiliations : _ Nationalité d’origine : atlante Ethnie réelle : aseryne (paleo-atlante) Statut : duc Leder Caendis est le duc de Valatar, un des anciens duchés. Il l’était avant le naufrage et servait Kalira elle-même à l’époque. Corsaire émérite il a écumé les mers intérieures d’Aèr en ayant été banni du Duché d’Aerilin. Il a plus que voyagé sur Terre à l’époque et sur Aèr par la suite. Sa Maison, très liée à la mer aurait été celle de Laera, la déesse des Océans sur Aèr quoi qu’on ne sache pas si elle était bien la fondatrice de cette maison comme le dit Leder ou, au contraire, une représentante rejetée qui fit valoir sa valeur par ses seules compétences jusqu’à mériter sa pierre divine. Leder n’a qu’une seule loyauté, elle va à Kalira et Kalira seule, cette dernière ayant reconnue Lorinae comme la seule reine légitime, il sert l’ancienne aventurière mais n’arrive pas à la voir comme autre chose qu’une remplaçante. Lorinae en a plus que conscience même s’il n’a jamais été frontalement irrespectueux. Il n’a AUCUN intérêt pour la Réalité et n’y a pas d’identité bien qu’il aurait été l’amant de la nymphe Amphitrite."},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Valatar: Leder Caendis"],["Nom de la Réalité","_"],["Nom de la Vérité","Leder Caendis"],["Âge source","« 70 ans » - ???? ans"],["Affiliations","_"],["Nationalité d’origine","atlante"],["Nature réelle","aseryne (paleo-atlante)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Leder Caendis est le duc de Valatar, un des anciens duchés. Il l’était avant le naufrage et servait Kalira elle-même à l’époque. Corsaire émérite il a écumé les mers intérieures d’Aèr en ayant été banni du Duché d’Aerilin. Il a plus que voyagé sur Terre à l’époque et sur Aèr par la suite. Sa Maison, très liée à la mer aurait été celle de Laera, la déesse des Océans sur Aèr quoi qu’on ne sache pas si elle était bien la fondatrice de cette maison comme le dit Leder ou, au contraire, une représentante rejetée qui fit valoir sa valeur par ses seules compétences jusqu’à mériter sa pierre divine. Leder n’a qu’une seule loyauté, elle va à Kalira et Kalira seule, cette dernière ayant reconnue Lorinae comme la seule reine légitime, il sert l’ancienne aventurière mais n’arrive pas à la voir comme autre chose qu’une remplaçante. Lorinae en a plus que conscience même s’il n’a jamais été frontalement irrespectueux. Il n’a AUCUN intérêt pour la Réalité et n’y a pas d’identité bien qu’il aurait été l’amant de la nymphe Amphitrite."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-inigo-andreas-03","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Inigo Andreas","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Inigo Andreas","real_name_source":"Inigo Andreas","nom_verite":"Ineleron Eydreas","nom_verite_source":"Ineleron Eydreas","race":"Aseryne (neo-atlante)","age":"«30 ans » - ???","origine":"Argentine","statut":"duc","affiliations":"Corporation : Nextar","source_group":"Atlantide","source_order":3,"source_page":10,"identity_keys":["Ineleron Eydreas","Inigo Andreas"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Shiren: Ineleron Eydreas Nom de la Réalité : Inigo Andreas Nom de la Vérité : Ineleron Eydreas Age : «30 ans » - ??? Affiliations : Corporation : Nextar Nationalité d’origine : Argentine Ethnie réelle : Aseryne (neo-atlante) Statut : duc Inigo est un brillant journaliste d’origine argentine, même s’il est blond aux yeux bleus, il a l’attitude d’un hispanique au sang chaud, il parle vite et agit souvent avant de réfléchir. Il a longuement tenté de séduire SHI Wei, sa patronne avant de comparaitre dans le bureau de Gabriella Austin, sa plus grande patronne encore… C’est un des plus jeunes ducs, il est né sur Aèr, dans le duché d’Aerilin, il a brillamment passé une partie de sa vie à la tour élémentaire où il fut formé comme un des meilleurs mages de sa promotion. Il n’a jamais atteint le titre d’archimage car c’est un être aussi ambitieux qu’inconstant. Avant que l’Atlantide ne soit sortie des flots, il essaya lui-même de réaliser ce miracle, mais il rata d’être tué par des aberrations de Thul qui y résidaient. Les trois quarts de son torse portent les stigmates de corruptions par l’énergie de Thul qu’il a endigué par sa magie, il le cache à la reine et aux autres ducs car personne ne sait ce qu’il a tenté de faire. Plus jeune, il était amoureux d’une amie de Lorinae, l’ancienne reine Nysril, mais elle le rejeta, il en garde une légère rancœur contre les elfes même si ceux de la Terre et ceux d’Aèr sont peu liés, pour lui, cela ne fait aucune différence."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Inigo Andreas"],["Âge apparent","30 ans"],["Nationalité déclarée","Argentine"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Shiren: Ineleron Eydreas"],["Nom de la Réalité","Inigo Andreas"],["Nom de la Vérité","Ineleron Eydreas"],["Âge source","«30 ans » - ???"],["Affiliations","Corporation : Nextar"],["Nationalité d’origine","Argentine"],["Nature réelle","Aseryne (neo-atlante)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Inigo est un brillant journaliste d’origine argentine, même s’il est blond aux yeux bleus, il a l’attitude d’un hispanique au sang chaud, il parle vite et agit souvent avant de réfléchir. Il a longuement tenté de séduire SHI Wei, sa patronne avant de comparaitre dans le bureau de Gabriella Austin, sa plus grande patronne encore… C’est un des plus jeunes ducs, il est né sur Aèr, dans le duché d’Aerilin, il a brillamment passé une partie de sa vie à la tour élémentaire où il fut formé comme un des meilleurs mages de sa promotion. Il n’a jamais atteint le titre d’archimage car c’est un être aussi ambitieux qu’inconstant. Avant que l’Atlantide ne soit sortie des flots, il essaya lui-même de réaliser ce miracle, mais il rata d’être tué par des aberrations de Thul qui y résidaient. Les trois quarts de son torse portent les stigmates de corruptions par l’énergie de Thul qu’il a endigué par sa magie, il le cache à la reine et aux autres ducs car personne ne sait ce qu’il a tenté de faire. Plus jeune, il était amoureux d’une amie de Lorinae, l’ancienne reine Nysril, mais elle le rejeta, il en garde une légère rancœur contre les elfes même si ceux de la Terre et ceux d’Aèr sont peu liés, pour lui, cela ne fait aucune différence."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-kyleane-natyel-04","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kyleane Natyel","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Kyleane Natyel","nom_verite_source":"Kyleane Natyel","race":"aseryne (paleo-atlante)","age":"«48 ans » - ???","origine":"atlante","statut":"duchesse","affiliations":"_","source_group":"Atlantide","source_order":4,"source_page":10,"identity_keys":["Kyleane Natyel"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Shael: Kyleane Natyel Nom de la Réalité : _ Nom de la Vérité :Kyleane Natyel Age : «48 ans » - ??? Affiliations : _ Nationalité d’origine : atlante Ethnie réelle : aseryne (paleo-atlante) Statut : duchesse Kyleane Natyel est la maitresse de la maison Natyel en charge du duché de Shael. Extrêmement désagréable et peu tolérante, elle n’a jamais supporté la « médiocrité » des aeriliens, les aseryns d’Aèr. Fantasmant la vie sur l’Atlantide, elle a rapidement déchanté en y débarquant. Tout était à reconstruire et les créatures y étaient hostiles. Après la naissance de sa quatrième fille, elle céda le titre ducal pour intégrer les rangs des cultistes du Temple pendant sa retraite. La maison Udrelis complota et s’installa à la tête du duché en supprimant chaque Natyel sur le chemin. Les maîtres de la maison Udrelis commirent l’erreur d’oublier Kyleane, qu’ils pensaient hors des intérêts de sa maison. Elle quitta le Temple et après quelques assassinats s’installa à nouveau comme prétendante au titre ducal, que la reine lui octroya. Malgré son âge avancé, sa main est encore très demandée et n’ayant pas de descendance directe, après elle, les Natyel s’éteindront probablement. C’est donc un enjeu politique que de trouver des descendants indirects ou un mari, en ce sens, les Mûliens l’ont bien noté même si elle les méprise."},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Shael: Kyleane Natyel"],["Nom de la Réalité","_"],["Nom de la Vérité","Kyleane Natyel"],["Âge source","«48 ans » - ???"],["Affiliations","_"],["Nationalité d’origine","atlante"],["Nature réelle","aseryne (paleo-atlante)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Kyleane Natyel est la maitresse de la maison Natyel en charge du duché de Shael. Extrêmement désagréable et peu tolérante, elle n’a jamais supporté la « médiocrité » des aeriliens, les aseryns d’Aèr. Fantasmant la vie sur l’Atlantide, elle a rapidement déchanté en y débarquant. Tout était à reconstruire et les créatures y étaient hostiles. Après la naissance de sa quatrième fille, elle céda le titre ducal pour intégrer les rangs des cultistes du Temple pendant sa retraite. La maison Udrelis complota et s’installa à la tête du duché en supprimant chaque Natyel sur le chemin. Les maîtres de la maison Udrelis commirent l’erreur d’oublier Kyleane, qu’ils pensaient hors des intérêts de sa maison. Elle quitta le Temple et après quelques assassinats s’installa à nouveau comme prétendante au titre ducal, que la reine lui octroya. Malgré son âge avancé, sa main est encore très demandée et n’ayant pas de descendance directe, après elle, les Natyel s’éteindront probablement. C’est donc un enjeu politique que de trouver des descendants indirects ou un mari, en ce sens, les Mûliens l’ont bien noté même si elle les méprise."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-larry-sundown-05","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Larry SUNDOWN","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Larry SUNDOWN","real_name_source":"Larry SUNDOWN","nom_verite":"Laetheas SUNDOSIA","nom_verite_source":"Laetheas SUNDOSIA","race":"Aseryne (neo-atlante)","age":"« 44 ans » - ???","origine":"Américaine","statut":"duc","affiliations":"pègre : mafia navale","source_group":"Atlantide","source_order":5,"source_page":11,"identity_keys":["Latheas Sundosia","Larry SUNDOWN","Laetheas SUNDOSIA"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Relaïa: Latheas Sundosia Nom de la Réalité : Larry SUNDOWN Nom de la Vérité : Laetheas SUNDOSIA Age : « 44 ans » - ??? Affiliations : pègre : mafia navale Nationalité d’origine : Américaine Ethnie réelle : Aseryne (neo-atlante) Statut : duc Larry Sundown est « officiellement » un crawler, un gundriver à la tête du « Speedthunder », un navire surpuissant et rapide permettant d’embarquer une cargaison limitée mais sûre. C’est en vérité le patron de « Red Captain », l’un des types les plus recherchés qui est à la tête d’une flotte de contrebande. Derrière ses tatouages, sa musculature démesurée et son visage terrifiant, Laethas est un duc de très haute lignée atlante. Né sur la nouvelle Atlantide, il admire Lorinae plus qu’aucune autre personne et s’est constitué lui-même sa force de frappe contre les Muliens. En effet, dans sa flotte de contrebande, il a une véritable flotte de guerre, même pas dissimulée une seconde, c’est ce qui fait sa force dans la Réalité mais lui sert aussi dans la Vérité. Il croit que Siobhain est une fille de Kyriak et cherche à l’approcher depuis longtemps. C’est un des rares ducs Atlantes parfaitement bien intégré dans la Réalité, bien plus qu’il ne l’est dans l’Atlantide. Pour cette raison, c’est sa jumelle, Laethia qui assure les tâches administratives pour le duché. Pendant la guerre de 22-28, il était marin sous les ordres de Farah Al’Arshad qu’il respecte encore beaucoup."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Larry SUNDOWN"],["Âge apparent","44 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Relaïa: Latheas Sundosia"],["Nom de la Réalité","Larry SUNDOWN"],["Nom de la Vérité","Laetheas SUNDOSIA"],["Âge source","« 44 ans » - ???"],["Affiliations","pègre : mafia navale"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (neo-atlante)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Larry Sundown est « officiellement » un crawler, un gundriver à la tête du « Speedthunder », un navire surpuissant et rapide permettant d’embarquer une cargaison limitée mais sûre. C’est en vérité le patron de « Red Captain », l’un des types les plus recherchés qui est à la tête d’une flotte de contrebande. Derrière ses tatouages, sa musculature démesurée et son visage terrifiant, Laethas est un duc de très haute lignée atlante. Né sur la nouvelle Atlantide, il admire Lorinae plus qu’aucune autre personne et s’est constitué lui-même sa force de frappe contre les Muliens. En effet, dans sa flotte de contrebande, il a une véritable flotte de guerre, même pas dissimulée une seconde, c’est ce qui fait sa force dans la Réalité mais lui sert aussi dans la Vérité. Il croit que Siobhain est une fille de Kyriak et cherche à l’approcher depuis longtemps. C’est un des rares ducs Atlantes parfaitement bien intégré dans la Réalité, bien plus qu’il ne l’est dans l’Atlantide. Pour cette raison, c’est sa jumelle, Laethia qui assure les tâches administratives pour le duché. Pendant la guerre de 22-28, il était marin sous les ordres de Farah Al’Arshad qu’il respecte encore beaucoup."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-leana-rast-06","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Leana Rast","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Leana Rast","real_name_source":"Leana Rast","nom_verite":"Illeanna Lisirast","nom_verite_source":"Illeanna Lisirast","race":"Aseryn (neo-atlante)","age":"«38 ans » - ???","origine":"brittanique","statut":"duchesse","affiliations":"Corporations : Byron industries","source_group":"Atlantide","source_order":6,"source_page":11,"identity_keys":["Ileanna Lisirast","Leana Rast","Illeanna Lisirast"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Sharaith: Ileanna Lisirast Nom de la Réalité : Leana Rast Nom de la Vérité : Illeanna Lisirast Age : «38 ans » - ??? Affiliations : Corporations : Byron industries Nationalité d’origine : brittanique Ethnie réelle : Aseryn (neo-atlante) Statut : duchesse Haut cadre de l’équipe personnelle de la présidente de Byron Industrie, Leana est une femme agressive et relativement méprisante. Sa loyauté envers sa présidente corporative est réelle mais elle ne laisse rien au hasard pour faire progresser la megacorporation. Duchesse de Sharaith c’est une femme atlante qui ramène beaucoup de fonds aux intérêts atlantes. Elle estimpliquée dans la conquête d’Hyperborée. Ileanna a une formation assez guerrière, sur Aèr, sa lignée était connue pour ses prouesses martiales et elle a tenu à être reconnue comme maitresse d’armes sur Aèr avant d’accéder au titre ducal sur Terre. Elle méprise les humains de la Terre et s’ennuie souvent dans la Réalité, elle a besoin d’action et s’est assuré d’avoir une assez grande richesse pour passer outres les lois Californienne. En 2000, elle était Leah Leave, dans le réseau privé d’information préexistant à la « Darksun Association », c‘est elle qui identifia clairement John silver comme le fils d’une princesse Mulienne. Elle a supposé un temps qu’il était le fils d’Ouranos, un dive primordial, ou bien d’un esprit élémentaire voire un Kochtchei mais en 2013, la mort du policier scella toute révélation possible."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Leana Rast"],["Âge apparent","38 ans"],["Nationalité déclarée","brittanique"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Sharaith: Ileanna Lisirast"],["Nom de la Réalité","Leana Rast"],["Nom de la Vérité","Illeanna Lisirast"],["Âge source","«38 ans » - ???"],["Affiliations","Corporations : Byron industries"],["Nationalité d’origine","brittanique"],["Nature réelle","Aseryn (neo-atlante)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Haut cadre de l’équipe personnelle de la présidente de Byron Industrie, Leana est une femme agressive et relativement méprisante. Sa loyauté envers sa présidente corporative est réelle mais elle ne laisse rien au hasard pour faire progresser la megacorporation. Duchesse de Sharaith c’est une femme atlante qui ramène beaucoup de fonds aux intérêts atlantes. Elle estimpliquée dans la conquête d’Hyperborée. Ileanna a une formation assez guerrière, sur Aèr, sa lignée était connue pour ses prouesses martiales et elle a tenu à être reconnue comme maitresse d’armes sur Aèr avant d’accéder au titre ducal sur Terre. Elle méprise les humains de la Terre et s’ennuie souvent dans la Réalité, elle a besoin d’action et s’est assuré d’avoir une assez grande richesse pour passer outres les lois Californienne. En 2000, elle était Leah Leave, dans le réseau privé d’information préexistant à la « Darksun Association », c‘est elle qui identifia clairement John silver comme le fils d’une princesse Mulienne. Elle a supposé un temps qu’il était le fils d’Ouranos, un dive primordial, ou bien d’un esprit élémentaire voire un Kochtchei mais en 2013, la mort du policier scella toute révélation possible."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-carolina-nates-07","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Carolina Nates","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Carolina Nates","real_name_source":"Katryn Ruthberg / Carolina Nates","nom_verite":"Hkelarana Nateas","nom_verite_source":"Hkelarana Nateas","race":"aseryne (neo-atlante)","age":"« 40 ans »","origine":"Américaine","statut":"duchesse","affiliations":"Corporatiste : Wellspring et Tuatha","source_group":"Atlantide","source_order":7,"source_page":12,"identity_keys":["Kelrana Nateas","Katryn Ruthberg / Carolina Nates","Katryn Ruthberg","Carolina Nates","Hkelarana Nateas"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Elisiel: Kelrana Nateas Nom de la Réalité : Katryn Ruthberg / Carolina Nates Nom de la Vérité : Hkelarana Nateas Age : « 40 ans » Affiliations : Corporatiste : Wellspring et Tuatha Nationalité d’origine : Américaine Ethnie réelle : aseryne (neo-atlante) Statut : duchesse Carolina Nates est un mannequin de la Tuatha, elle est assez célèbre quoi qu’elle ne travaille que très peu, sa rareté sur les estrades ou la publicité augmente sa demande. La raison à cette absence régulière est que c’est un haut cadre de Wellspring du nom de Katryn Ruthberg, une redoutable femme d’affaire aussi plantureuse que sournoise. La duchesse d’Elisiel a pour projet de recréer une couronne absolue des Aseryns, une couronne des quatre royaumes, une couronne impériale atlante. Elle apprécie grandement Lorinae mais sa légitimité est difficilement reconnue dans les autres îles-continents atlantes, c’est pourquoi Kelrana complote avec le mulien Sagarion. Elle cherche un candidat indiscutable, elle travaille sur trois plans : le premier est de marier Kyriak à Lorinae, unissant deux des couronnes ainsi. La seconde option est de cloner Kalira Athegos, vénérée par tous les aseryns. Le dernier plan est de chercher une descendance Athegos secrète, mais les pistes sont maigres : la seule prétendante était Kessalia qui devint une déesse d’Aèr."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Carolina Nates"],["Âge apparent","40 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Elisiel: Kelrana Nateas"],["Nom de la Réalité","Katryn Ruthberg / Carolina Nates"],["Nom de la Vérité","Hkelarana Nateas"],["Âge source","« 40 ans »"],["Affiliations","Corporatiste : Wellspring et Tuatha"],["Nationalité d’origine","Américaine"],["Nature réelle","aseryne (neo-atlante)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Carolina Nates est un mannequin de la Tuatha, elle est assez célèbre quoi qu’elle ne travaille que très peu, sa rareté sur les estrades ou la publicité augmente sa demande. La raison à cette absence régulière est que c’est un haut cadre de Wellspring du nom de Katryn Ruthberg, une redoutable femme d’affaire aussi plantureuse que sournoise. La duchesse d’Elisiel a pour projet de recréer une couronne absolue des Aseryns, une couronne des quatre royaumes, une couronne impériale atlante. Elle apprécie grandement Lorinae mais sa légitimité est difficilement reconnue dans les autres îles-continents atlantes, c’est pourquoi Kelrana complote avec le mulien Sagarion. Elle cherche un candidat indiscutable, elle travaille sur trois plans : le premier est de marier Kyriak à Lorinae, unissant deux des couronnes ainsi. La seconde option est de cloner Kalira Athegos, vénérée par tous les aseryns. Le dernier plan est de chercher une descendance Athegos secrète, mais les pistes sont maigres : la seule prétendante était Kessalia qui devint une déesse d’Aèr."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-jason-collin-08","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Jason Collin","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Jason Collin","real_name_source":"Jason Collin","nom_verite":"Jesaen Seryn","nom_verite_source":"Jesaen Seryn","race":"Aseryne (paleo-atlante)","age":"« 45 ans » -","origine":"Américaine","statut":"duc","affiliations":"Gouvernementale : CBII","source_group":"Atlantide","source_order":8,"source_page":12,"identity_keys":["Jesaen Seryn","Jason Collin"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Laenadur : Jesaen Seryn Nom de la Réalité : Jason Collin Nom de la Vérité : Jesaen Seryn Age : « 45 ans » - Affiliations : Gouvernementale : CBII Nationalité d’origine : Américaine Ethnie réelle : Aseryne (paleo-atlante) Statut : duc Jason Collin est un cadre du CBII. Ce n’est pas un agent de terrain et il n’aime pas vraiment l’idée d’avoir à envoyer des gens enquêter, il voit la police Californienne comme une institution grandement plus efficace qu’aucune agence actuelle ne l’est. Rigide et intransigeant, il est protocolaire et souffre dans la société de 2035, où il apparait peu adapté, de manière presque pathologique. Ill peine dans sa vie sexuelle pour ça, essayant d’être romantique. Jesaen est un aseryn né sur Terrer. Assez ancien, c’était une sorte de chevalier servant la reine Aerlith avant de monter dans sa Maison après le décès de son oncle. Si cet esprit chevaleresque n’est pas le plus développé chez les atlantes, c’est justement un trait de personnalité propre de Jesean que d’idolâtrer ces valeurs. Il fit partie des « Preux de Nyria » sur Gaerras seconde même s’il retourna sur son monde après la croisade. Sur Terra Umbra, il est plus lassé qu’inadapté en vérité, la vulgarité et la bassesse le rendent aigri, être au CBII est une façon pour lui de se donner bonne conscience, il aide la société à se corriger. Il possède un diablotin (dackeros) qui possède son holophone et lui sert d’espion."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Jason Collin"],["Âge apparent","45 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Laenadur : Jesaen Seryn"],["Nom de la Réalité","Jason Collin"],["Nom de la Vérité","Jesaen Seryn"],["Âge source","« 45 ans » -"],["Affiliations","Gouvernementale : CBII"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (paleo-atlante)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Jason Collin est un cadre du CBII. Ce n’est pas un agent de terrain et il n’aime pas vraiment l’idée d’avoir à envoyer des gens enquêter, il voit la police Californienne comme une institution grandement plus efficace qu’aucune agence actuelle ne l’est. Rigide et intransigeant, il est protocolaire et souffre dans la société de 2035, où il apparait peu adapté, de manière presque pathologique. Ill peine dans sa vie sexuelle pour ça, essayant d’être romantique. Jesaen est un aseryn né sur Terrer. Assez ancien, c’était une sorte de chevalier servant la reine Aerlith avant de monter dans sa Maison après le décès de son oncle. Si cet esprit chevaleresque n’est pas le plus développé chez les atlantes, c’est justement un trait de personnalité propre de Jesean que d’idolâtrer ces valeurs. Il fit partie des « Preux de Nyria » sur Gaerras seconde même s’il retourna sur son monde après la croisade. Sur Terra Umbra, il est plus lassé qu’inadapté en vérité, la vulgarité et la bassesse le rendent aigri, être au CBII est une façon pour lui de se donner bonne conscience, il aide la société à se corriger. Il possède un diablotin (dackeros) qui possède son holophone et lui sert d’espion."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-erlaris-selerias-09","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Erlaris Selerias","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Erlaris Selerias","nom_verite_source":"Erlaris Selerias","race":"aseryne (paleo-atlante)","age":"«75 ans » - ???","origine":"Atlante","statut":"duc","affiliations":"_","source_group":"Atlantide","source_order":9,"source_page":13,"identity_keys":["Erlaris Selerias"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Caliel: Erlaris Selerias Nom de la Réalité : _ Nom de la Vérité : Erlaris Selerias Age : «75 ans » - ??? Affiliations : _ Nationalité d’origine : Atlante Ethnie réelle : aseryne (paleo-atlante) Statut : duc Si l’’héroïsme a bien des noms chez les atlantes, Erlaris Selerias en est un. Immortel, il l’était devenu en traquant les khinaes sur l’Atlantide bien avant son naufrage. Il est plus ancien que la reine Kalira et était déjà duc quand elle était jeune. Malgré tout, quand l’île-continent coula, il resta à ses cotés et fut un des rares à ne pas quitter l’île même engloutie. Il devint prisonnier d’une bulle dans les cavités de Stroethil sans aller en Stase. Il y demeura jusqu’à ce qu’on ne ressorte l’Atlantide des flots. Pendant ce temps, il lutta contre les abyssaux et les rocréens envahissant les lieux. Il ne fit pas que survivre puisque dans la bulle d’air autour d’Atlantis, la capitale, il défendit et entretint le palais de la reine des millénaires. Son corps est meurtri et abimé par les combats contre les abominations et malgré tout, il a encore une aura de puissance et de charisme malgré son âge et ses blessures. Il maitrise mal la politique entre l’Atlantide et ses rivales, ne comprenant pas les divergences entre aseryns. C’était le mentor de Kyriak, alors il est furieux contre le « gamin » d’être devenu un traitre. Sa lignée avait perduré sur Aèr mais Erlaris III était un dépravé dégénéré, alors Erlaris premier reprit le titre ducal qui lui revenait de plein droit. Il terrifie les autres ducs atlantes car il entend la voix de Thul et de ses créatures."},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Caliel: Erlaris Selerias"],["Nom de la Réalité","_"],["Nom de la Vérité","Erlaris Selerias"],["Âge source","«75 ans » - ???"],["Affiliations","_"],["Nationalité d’origine","Atlante"],["Nature réelle","aseryne (paleo-atlante)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Si l’’héroïsme a bien des noms chez les atlantes, Erlaris Selerias en est un. Immortel, il l’était devenu en traquant les khinaes sur l’Atlantide bien avant son naufrage. Il est plus ancien que la reine Kalira et était déjà duc quand elle était jeune. Malgré tout, quand l’île-continent coula, il resta à ses cotés et fut un des rares à ne pas quitter l’île même engloutie. Il devint prisonnier d’une bulle dans les cavités de Stroethil sans aller en Stase. Il y demeura jusqu’à ce qu’on ne ressorte l’Atlantide des flots. Pendant ce temps, il lutta contre les abyssaux et les rocréens envahissant les lieux. Il ne fit pas que survivre puisque dans la bulle d’air autour d’Atlantis, la capitale, il défendit et entretint le palais de la reine des millénaires. Son corps est meurtri et abimé par les combats contre les abominations et malgré tout, il a encore une aura de puissance et de charisme malgré son âge et ses blessures. Il maitrise mal la politique entre l’Atlantide et ses rivales, ne comprenant pas les divergences entre aseryns. C’était le mentor de Kyriak, alors il est furieux contre le « gamin » d’être devenu un traitre. Sa lignée avait perduré sur Aèr mais Erlaris III était un dépravé dégénéré, alors Erlaris premier reprit le titre ducal qui lui revenait de plein droit. Il terrifie les autres ducs atlantes car il entend la voix de Thul et de ses créatures."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-kayden-todds-10","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kayden Todds","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Kayden Todds","real_name_source":"Kayden Todds","nom_verite":"Meldaen Lisathas","nom_verite_source":"Meldaen Lisathas","race":"Aseryne (neo-atlante)","age":"«20 ans » - ????","origine":"irlandaise","statut":"duc","affiliations":"Corporation : tala","source_group":"Atlantide","source_order":10,"source_page":13,"identity_keys":["Melsaen Lisathas","Kayden Todds","Meldaen Lisathas"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Ilassa : Melsaen Lisathas Nom de la Réalité : Kayden Todds Nom de la Vérité : Meldaen Lisathas Age : «20 ans » - ???? Affiliations : Corporation : tala Nationalité d’origine : irlandaise Ethnie réelle : Aseryne (neo-atlante) Statut : duc Kayden Todds est un directeur de sous-branche à la Tala corporation, il est sous les ordres d’Oliver King, lui-même directement au service de la présidente Tokala. De fait, c’est le propriétaire du « Leprechaun » un grand casino irlandais. Kayden est connu pour être très joueur et très flambeur malgré sa position, il aime tout réglé par un jeu de hasard. Moqueur et provocateur, ce jeune irlandais n’est pas très combattif même s’il ne semble craindre qu’assez peu de choses. Meldean est un duc Atlante. Parce que les aseryns agissent très vite, parfois plus vite qu’ils ne réfléchissent, un casino est devenu une évidence pour servir à les repérer, presque toujours, un aseryn sera le premier à parier gros, le Lepreuchaun étant un vaste piège pour les ficher quand ils ne sont pas Atlantes. Il a quelques soucis avec la mafia Irlandaise qu’il ne s’attendait pas à joindre. Il est fou de l’ancienne reine Aerlith. Il porte toujours des gants pour cacher une cicatrice à sa main gauche, un coup de couteau d’un mafieux pour l’intimider y étant trop visible."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Kayden Todds"],["Âge apparent","20 ans"],["Nationalité déclarée","irlandaise"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Ilassa : Melsaen Lisathas"],["Nom de la Réalité","Kayden Todds"],["Nom de la Vérité","Meldaen Lisathas"],["Âge source","«20 ans » - ????"],["Affiliations","Corporation : tala"],["Nationalité d’origine","irlandaise"],["Nature réelle","Aseryne (neo-atlante)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Kayden Todds est un directeur de sous-branche à la Tala corporation, il est sous les ordres d’Oliver King, lui-même directement au service de la présidente Tokala. De fait, c’est le propriétaire du « Leprechaun » un grand casino irlandais. Kayden est connu pour être très joueur et très flambeur malgré sa position, il aime tout réglé par un jeu de hasard. Moqueur et provocateur, ce jeune irlandais n’est pas très combattif même s’il ne semble craindre qu’assez peu de choses. Meldean est un duc Atlante. Parce que les aseryns agissent très vite, parfois plus vite qu’ils ne réfléchissent, un casino est devenu une évidence pour servir à les repérer, presque toujours, un aseryn sera le premier à parier gros, le Lepreuchaun étant un vaste piège pour les ficher quand ils ne sont pas Atlantes. Il a quelques soucis avec la mafia Irlandaise qu’il ne s’attendait pas à joindre. Il est fou de l’ancienne reine Aerlith. Il porte toujours des gants pour cacher une cicatrice à sa main gauche, un coup de couteau d’un mafieux pour l’intimider y étant trop visible."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-terra-erill-11","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Terra Erill","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Terra Erill","real_name_source":"Terra Erill","nom_verite":"aeril Theanai","nom_verite_source":"aeril Theanai","race":"Aseryne (neo-atlante)","age":"«34 ans » -","origine":"Australie","statut":"duchesse","affiliations":"crawlers : venomer","source_group":"Atlantide","source_order":11,"source_page":14,"identity_keys":["Aeril Theanai","Terra Erill","aeril Theanai"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Sondassa: Aeril Theanai Nom de la Réalité : Terra Erill Nom de la Vérité : aeril Theanai Age : «34 ans » - Affiliations : crawlers : venomer Nationalité d’origine : Australie Ethnie réelle : Aseryne (neo-atlante) Statut : duchesse Terra était un médecin de l’Hôpital public qui a perdu son droit d’exercé. Après avoir survécu quelques années à changer de régions puis de pays, entre l’Australie, l’Afrique du sud, l’Angleterre et les Etats￾Unis, elle a fini par être assez recherchée comme « le médecin fou ». Proche des laboratoires Foster, elle a sa propre « clinique » de venomer où elle fait ses expériences en dehors de tout cadre. En voyant son visage assez souvent déformé par un sourire dément à l’idée de tester des choses, on ne penserait pas avoir une des plus nobles duchesses atlantes au monde, en effet la lignée Theanai a du sang Athegos par la cousine de Kalira. Aeril est une érudite et sa soif de connaissance en a fait une femme avide d’expérimentation, Los Angeles de 2035 lui offre un laboratoire géant et ses amitiés avec Ryan Foster, le mage Faust et avec Feryel Sehdia, Fearys, lui sont autant de relations utiles que motivantes. Elle était de l’équipe de Levanah au PCRC et adopta un style neopunk au contact de Leslie Wright. C’est elle qui travaille sur le plan « clonage » de Kelrana, éduquant déjà un clone « raté » supposément d’Aerlith comme sa fille, à la suite d’un plan abandonné."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Terra Erill"],["Âge apparent","34 ans"],["Nationalité déclarée","Australie"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Sondassa: Aeril Theanai"],["Nom de la Réalité","Terra Erill"],["Nom de la Vérité","aeril Theanai"],["Âge source","«34 ans » -"],["Affiliations","crawlers : venomer"],["Nationalité d’origine","Australie"],["Nature réelle","Aseryne (neo-atlante)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Terra était un médecin de l’Hôpital public qui a perdu son droit d’exercé. Après avoir survécu quelques années à changer de régions puis de pays, entre l’Australie, l’Afrique du sud, l’Angleterre et les Etats￾Unis, elle a fini par être assez recherchée comme « le médecin fou ». Proche des laboratoires Foster, elle a sa propre « clinique » de venomer où elle fait ses expériences en dehors de tout cadre. En voyant son visage assez souvent déformé par un sourire dément à l’idée de tester des choses, on ne penserait pas avoir une des plus nobles duchesses atlantes au monde, en effet la lignée Theanai a du sang Athegos par la cousine de Kalira. Aeril est une érudite et sa soif de connaissance en a fait une femme avide d’expérimentation, Los Angeles de 2035 lui offre un laboratoire géant et ses amitiés avec Ryan Foster, le mage Faust et avec Feryel Sehdia, Fearys, lui sont autant de relations utiles que motivantes. Elle était de l’équipe de Levanah au PCRC et adopta un style neopunk au contact de Leslie Wright. C’est elle qui travaille sur le plan « clonage » de Kelrana, éduquant déjà un clone « raté » supposément d’Aerlith comme sa fille, à la suite d’un plan abandonné."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-nathalia-kayrianov-12","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Nathalia Kayrianov","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Nathalia Kayrianov","real_name_source":"Nathalia Kayrianov","nom_verite":"Naleyn Cairiah","nom_verite_source":"Naleyn Cairiah","race":"aseryne (paleo-atlante)","age":"«43 ans » - ???","origine":"Russe","statut":"duchesse","affiliations":"crawlers : mercs","source_group":"Atlantide","source_order":12,"source_page":14,"identity_keys":["Naleyn Cairiah","Nathalia Kayrianov"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Lassira : Naleyn Cairiah Nom de la Réalité : Nathalia Kayrianov Nom de la Vérité : Naleyn Cairiah Age : «43 ans » - ??? Affiliations : crawlers : mercs Nationalité d’origine : Russe Ethnie réelle : aseryne (paleo-atlante) Statut : duchesse Ex militaire de Russie, elle a émigré après la guerre de 22-28 pour fuir le grand effondrement russe. Elle était dans les troupes d’Andrea Shield mais son besoin de liberté lui fit basculer dans la vie de crawler. Bien qu’elle conserve sa rigueur militaire et une certaine rudesse, elle bosse avec d’anciens russes le plus souvent, ne craignant pas de bosser pour la Bratva sans vouloir en être dépendante. Bien qu’elle joue les mercenaires badass, Naleyn est une duchesse de très haute noblesse atlante, elle se teint les cheveux pour paraitre plus brune, les aseryn ayant souvent les cheveux plus clairs. Elle a un sens du devoir exacerbé et n’est plus une jeune demoiselle atlante. Elle a un parfait contrôle d’elle￾même, s’efforçant au quotidien de rester froide malgré sa nature électrique. Mieux vaut ne pas l’énerver néanmoins, si elle se lâche, elle devient assez sanguinaire et démesurée dans ses actes. Elle cherche dans la Réalité à vivre une nouvelle jeunesse, plus libre et moins pesante que celle qu’elle vécut. Elle cherche aussi un sabre maudit de Mu dénommé « Higashizono », il contient un fléau supérieur ayant dévoré son ancêtre."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Nathalia Kayrianov"],["Âge apparent","43 ans"],["Nationalité déclarée","Russe"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Lassira : Naleyn Cairiah"],["Nom de la Réalité","Nathalia Kayrianov"],["Nom de la Vérité","Naleyn Cairiah"],["Âge source","«43 ans » - ???"],["Affiliations","crawlers : mercs"],["Nationalité d’origine","Russe"],["Nature réelle","aseryne (paleo-atlante)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Ex militaire de Russie, elle a émigré après la guerre de 22-28 pour fuir le grand effondrement russe. Elle était dans les troupes d’Andrea Shield mais son besoin de liberté lui fit basculer dans la vie de crawler. Bien qu’elle conserve sa rigueur militaire et une certaine rudesse, elle bosse avec d’anciens russes le plus souvent, ne craignant pas de bosser pour la Bratva sans vouloir en être dépendante. Bien qu’elle joue les mercenaires badass, Naleyn est une duchesse de très haute noblesse atlante, elle se teint les cheveux pour paraitre plus brune, les aseryn ayant souvent les cheveux plus clairs. Elle a un sens du devoir exacerbé et n’est plus une jeune demoiselle atlante. Elle a un parfait contrôle d’elle￾même, s’efforçant au quotidien de rester froide malgré sa nature électrique. Mieux vaut ne pas l’énerver néanmoins, si elle se lâche, elle devient assez sanguinaire et démesurée dans ses actes. Elle cherche dans la Réalité à vivre une nouvelle jeunesse, plus libre et moins pesante que celle qu’elle vécut. Elle cherche aussi un sabre maudit de Mu dénommé « Higashizono », il contient un fléau supérieur ayant dévoré son ancêtre."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-kyle-smith-13","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kyle Smith","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Kyle Smith","real_name_source":"Kyle Smith","nom_verite":"Keelean Erith","nom_verite_source":"Keelean Erith","race":"aseryne (neo-atlante)","age":"«32 ans » - ???","origine":"australienne","statut":"Duc","affiliations":"crawlers : voidrunner","source_group":"Atlantide","source_order":13,"source_page":15,"identity_keys":["Keelean Erith","Kyle Smith"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Ilast : Keelean Erith Nom de la Réalité : Kyle Smith Nom de la Vérité : Keelean Erith Age : «32 ans » - ??? Affiliations : crawlers : voidrunner Nationalité d’origine : australienne Ethnie réelle : aseryne (neo-atlante) Statut : Duc Kyle est un assassin, un crawler de type « voidrunner », rapide et méticuleux, il déteste travailler seul, il constitut toujours une équipe de 4 à 10 personnes, souvent avec des crawlers amateurs afin de les plumer au besoin. Derrière ses airs assez farouches et effrayant, c’est un type assez bienveillant, il fait assassin parce que ça paye bien plus, c’est l’unique raison. Keelean a été officiellement assassiné par des Muliens il y a quelques années à peine. C’était en représailles de la mort de John Silver, un petit fils du roi mulien, Kyriak. Des assassins muliens pénétrèrent dans l’Atlantide et le trucidèrent, un duc de grande lignée contre un bâtard de princesse bâtarde. Il survécut par miracle, grâce au sang altéré par la stase mais décida de traquer ceux ayant osé frapper dans le royaume sacré. Depuis une vingtaine d’année il en a tué plusieurs mais il cherche encore l’instigatrice, la mère de John Silver. Il est farouchement haineux envers les Muliens et c’est possiblement le plus véhément à leur égard : c’est le duc qui prône le plus la guerre. Sa mort officielle lui permet sa traque, c’est sa femme, Adryerra, qui assure le rôle de duchesse en son absence."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Kyle Smith"],["Âge apparent","32 ans"],["Nationalité déclarée","australienne"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Ilast : Keelean Erith"],["Nom de la Réalité","Kyle Smith"],["Nom de la Vérité","Keelean Erith"],["Âge source","«32 ans » - ???"],["Affiliations","crawlers : voidrunner"],["Nationalité d’origine","australienne"],["Nature réelle","aseryne (neo-atlante)"],["Statut","Duc"]]},{"type":"p","style":"lore","text":"Kyle est un assassin, un crawler de type « voidrunner », rapide et méticuleux, il déteste travailler seul, il constitut toujours une équipe de 4 à 10 personnes, souvent avec des crawlers amateurs afin de les plumer au besoin. Derrière ses airs assez farouches et effrayant, c’est un type assez bienveillant, il fait assassin parce que ça paye bien plus, c’est l’unique raison. Keelean a été officiellement assassiné par des Muliens il y a quelques années à peine. C’était en représailles de la mort de John Silver, un petit fils du roi mulien, Kyriak. Des assassins muliens pénétrèrent dans l’Atlantide et le trucidèrent, un duc de grande lignée contre un bâtard de princesse bâtarde. Il survécut par miracle, grâce au sang altéré par la stase mais décida de traquer ceux ayant osé frapper dans le royaume sacré. Depuis une vingtaine d’année il en a tué plusieurs mais il cherche encore l’instigatrice, la mère de John Silver. Il est farouchement haineux envers les Muliens et c’est possiblement le plus véhément à leur égard : c’est le duc qui prône le plus la guerre. Sa mort officielle lui permet sa traque, c’est sa femme, Adryerra, qui assure le rôle de duchesse en son absence."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-katelyn-attenborough-14","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Katelyn Attenborough","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Atlantide","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Katelyn Attenborough","real_name_source":"Katelyn Attenborough","nom_verite":"Kalira Athegos","nom_verite_source":"Kalira Athegos","race":"aseryne (paleo-atlante)","age":"«57 ans » - ??? ans","origine":"Américaine","statut":"Ancienne Reine","affiliations":"Gouvernement","source_group":"Atlantide","source_order":14,"source_page":15,"identity_keys":["Kalira Athegos","Katelyn Attenborough"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Ancienne reine: Kalira Athegos Nom de la Réalité : Katelyn Attenborough Nom de la Vérité : Kalira Athegos Age : «57 ans » - ??? ans Affiliations : Gouvernement Nationalité d’origine : Américaine Ethnie réelle : aseryne (paleo-atlante) Statut : Ancienne Reine Experte juridique dans les années 2000, elle était détachée de l’inspection des finances pour assister le LAPD. Elle devint officieusement le numéro deux du LAPD et fut séduite par le charismatique et tout jeune John Silver, un enquêteur prometteur qui faisait un sacré duo avec Edward Henry. Hélas, elle disparut sans laisser de trace après avoir incriminé des cadres de la police, laissant une fille à son conjoint. Kalira Athegos est très loin d’être qu’une beauté atlante parfaite, c’est la plus grande reine ayant jamais gouverné, la plus aimée, son charme est grand hélas ses amours ont mené à une catastrophe, mère de Mylakai, un des plus grands héros d’Aèr. Elle est une femme vertueuse et extrêmement sérieuse. C’est à elle que l’on doit l’établissement de la colonie Altéras sur Gaerras seconde par exemple. Outre ses talents de grande manieuse de la foudre, elle a une intelligence rare, capable planifier le commercer entre trois mondes. Plus que quiconque, elle sait la difficulté derrière l’unification des aseryns de la Terre. Elle est si ancienne qu’elle a probablement autant de pouvoirs et de savoirs qu’une divinité, c’est pourquoi certains aseryns l’ont déifié en dehors de l’Atlantide. Elle a aussi parfaitement conscience de la menace des Fléaux dont le grand ennemi des Atlantes : Thul. Elle est toujours accompagnée de l’ex-impératrice Reikiko, de Gaerras II, qu’elle a grandement élevé."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Katelyn Attenborough"],["Âge apparent","57 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Ancienne reine: Kalira Athegos"],["Nom de la Réalité","Katelyn Attenborough"],["Nom de la Vérité","Kalira Athegos"],["Âge source","«57 ans » - ??? ans"],["Affiliations","Gouvernement"],["Nationalité d’origine","Américaine"],["Nature réelle","aseryne (paleo-atlante)"],["Statut","Ancienne Reine"]]},{"type":"p","style":"lore","text":"Experte juridique dans les années 2000, elle était détachée de l’inspection des finances pour assister le LAPD. Elle devint officieusement le numéro deux du LAPD et fut séduite par le charismatique et tout jeune John Silver, un enquêteur prometteur qui faisait un sacré duo avec Edward Henry. Hélas, elle disparut sans laisser de trace après avoir incriminé des cadres de la police, laissant une fille à son conjoint. Kalira Athegos est très loin d’être qu’une beauté atlante parfaite, c’est la plus grande reine ayant jamais gouverné, la plus aimée, son charme est grand hélas ses amours ont mené à une catastrophe, mère de Mylakai, un des plus grands héros d’Aèr. Elle est une femme vertueuse et extrêmement sérieuse. C’est à elle que l’on doit l’établissement de la colonie Altéras sur Gaerras seconde par exemple. Outre ses talents de grande manieuse de la foudre, elle a une intelligence rare, capable planifier le commercer entre trois mondes. Plus que quiconque, elle sait la difficulté derrière l’unification des aseryns de la Terre. Elle est si ancienne qu’elle a probablement autant de pouvoirs et de savoirs qu’une divinité, c’est pourquoi certains aseryns l’ont déifié en dehors de l’Atlantide. Elle a aussi parfaitement conscience de la menace des Fléaux dont le grand ennemi des Atlantes : Thul. Elle est toujours accompagnée de l’ex-impératrice Reikiko, de Gaerras II, qu’elle a grandement élevé."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-kyriakos-zenos-15","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kyriakos Zenos","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Mû","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Kyriakos Zenos","real_name_source":"Kyriakos Zenos","nom_verite":"Kyriak Zenos Athegos","nom_verite_source":"Kyriak Zenos Athegos","race":"Aseryne (paleo-atlante)","age":"«64 ans » - ??? ns","origine":"grecque","statut":"Roi des Mûliens","affiliations":"corporatiste : seawares","source_group":"Mû","source_order":15,"source_page":19,"identity_keys":["Kyriak Zenos Athegos","Kyriakos Zenos"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Trône royal : Kyriak Zenos Athegos Nom de la Réalité : Kyriakos Zenos Nom de la Vérité : Kyriak Zenos Athegos Age : «64 ans » - ??? ns Affiliations : corporatiste : seawares Nationalité d’origine : grecque Ethnie réelle : Aseryne (paleo-atlante) Statut : Roi des Mûliens C’est le vice-président de Seaware, il est le bras-droit de Silia-Ellen depuis longtemps bien qu’ils ne s’entendent pas toujours, il protège presque toujours ses intérêts. Charismatique et rusé homme d’affaire, il est connu pour ses innombrables conquêtes, l’âge ne l’arrêtant pas. Cousin par leur arrière-grand-père commun avec Kalira Athegos, c’était un noble de la maison Athegos qui était assez jeune quand Sil’Elaith coula l’Atlantide, la maison Athegos fut redoutablement touchée, il se refusa à aller en Stase, décidant de joindre le continent avec des survivants. Lui et quelques autres nobles et braves traversèrent l’océan et s’installèrent en Grèce. Une part y demeura tandis que le reste se prépara à se séparer pour joindre Hyperborée, Lemuria et Mû. Kyriak se décida à affronter Thul pour regagner Mü, organisant longuement en plusieurs siècle une flotte pour ce dessein. Aidé par la déesse Abigor, son amante, il rallia la nymphe Amphitrite et la déesse Alabor, afin de mener une guerre en leurs nom contre les profonds de Mû, libérant quelques aseryns captifs y ayant survécu. Il ne tenta pas de sauver l’Atlantide car le plus puissant fléau de thul s’y trouvait, une engeance de Shaoggith. Roi de Mû qu’il sauva et fit repeupler, il est un héros sans égal pour les Muliens. Le retour des Aseryns d’Aer lui a causé un dilemme, mais quand il réalisa que la reine était une Darksun, il campa sur ses positions."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Kyriakos Zenos"],["Âge apparent","64 ans"],["Nationalité déclarée","grecque"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Trône royal : Kyriak Zenos Athegos"],["Nom de la Réalité","Kyriakos Zenos"],["Nom de la Vérité","Kyriak Zenos Athegos"],["Âge source","«64 ans » - ??? ns"],["Affiliations","corporatiste : seawares"],["Nationalité d’origine","grecque"],["Nature réelle","Aseryne (paleo-atlante)"],["Statut","Roi des Mûliens"]]},{"type":"p","style":"lore","text":"C’est le vice-président de Seaware, il est le bras-droit de Silia-Ellen depuis longtemps bien qu’ils ne s’entendent pas toujours, il protège presque toujours ses intérêts. Charismatique et rusé homme d’affaire, il est connu pour ses innombrables conquêtes, l’âge ne l’arrêtant pas. Cousin par leur arrière-grand-père commun avec Kalira Athegos, c’était un noble de la maison Athegos qui était assez jeune quand Sil’Elaith coula l’Atlantide, la maison Athegos fut redoutablement touchée, il se refusa à aller en Stase, décidant de joindre le continent avec des survivants. Lui et quelques autres nobles et braves traversèrent l’océan et s’installèrent en Grèce. Une part y demeura tandis que le reste se prépara à se séparer pour joindre Hyperborée, Lemuria et Mû. Kyriak se décida à affronter Thul pour regagner Mü, organisant longuement en plusieurs siècle une flotte pour ce dessein. Aidé par la déesse Abigor, son amante, il rallia la nymphe Amphitrite et la déesse Alabor, afin de mener une guerre en leurs nom contre les profonds de Mû, libérant quelques aseryns captifs y ayant survécu. Il ne tenta pas de sauver l’Atlantide car le plus puissant fléau de thul s’y trouvait, une engeance de Shaoggith. Roi de Mû qu’il sauva et fit repeupler, il est un héros sans égal pour les Muliens. Le retour des Aseryns d’Aer lui a causé un dilemme, mais quand il réalisa que la reine était une Darksun, il campa sur ses positions."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-collin-perez-16","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Collin Perez","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Mû","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Collin Perez","real_name_source":"Collin Perez","nom_verite":"Sagarion Nagilia","nom_verite_source":"Sagarion Nagilia","race":"aseryne (mûlienne)","age":"« 31ans » - ???? ans","origine":"américaine","statut":"duc","affiliations":"gouvernemental : maire (Phoenix)","source_group":"Mû","source_order":16,"source_page":19,"identity_keys":["Sagarion Nagilia","Collin Perez"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Amrica : Sagarion Nagilia Nom de la Réalité : Collin Perez Nom de la Vérité : Sagarion Nagilia Age : « 31ans » - ???? ans Affiliations : gouvernemental : maire (Phoenix) Nationalité d’origine : américaine Ethnie réelle : aseryne (mûlienne) Statut : duc Collin Perez est le maire de Phoenix et est en guerre contre les corporatistes un peu trop sauvage dans sa ville, pourtant intégrée à la grande Californie, la grande cité n’est pas aussi respectée. C’est un ami du président des Etats-Unis Seth Dirkman. Sagarion est issu de la maison Lisathas, les Nagilia n’en étant qu’une branche bâtarde apparue après la catastrophe. Malgré des airs assez nobles et respectable, Sagarion est un traitre et un comploteur. Il déteste Kyriak et lorgne sur le trône Mûlien. Pour y arriver, il complote avec la duchesse Kelrana Natheas, de l’Atlantide, afin d’unir une princesse Mulienne à un noble d’importance Atlante. Sagarion comptant installer ce couple à la tête de Mû puis remplacer le mari afin de poursuivre les négociations avec les atlantes, hélas, Kelrana ne propose personne qui existe. Son plus gros défi est de gérer l’existence de Kalira Athegos, la vraie reine légitime de tous les Aseryns. C’est lui qui avait fait tuer la descendance de Kyriak son petit-fils John Silver. Il sert la princesse Deidea Eina Zenos, son amante et marionnette dans ses complots."},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Collin Perez"],["Âge apparent","31ans"],["Nationalité déclarée","américaine"]]}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Amrica : Sagarion Nagilia"],["Nom de la Réalité","Collin Perez"],["Nom de la Vérité","Sagarion Nagilia"],["Âge source","« 31ans » - ???? ans"],["Affiliations","gouvernemental : maire (Phoenix)"],["Nationalité d’origine","américaine"],["Nature réelle","aseryne (mûlienne)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Collin Perez est le maire de Phoenix et est en guerre contre les corporatistes un peu trop sauvage dans sa ville, pourtant intégrée à la grande Californie, la grande cité n’est pas aussi respectée. C’est un ami du président des Etats-Unis Seth Dirkman. Sagarion est issu de la maison Lisathas, les Nagilia n’en étant qu’une branche bâtarde apparue après la catastrophe. Malgré des airs assez nobles et respectable, Sagarion est un traitre et un comploteur. Il déteste Kyriak et lorgne sur le trône Mûlien. Pour y arriver, il complote avec la duchesse Kelrana Natheas, de l’Atlantide, afin d’unir une princesse Mulienne à un noble d’importance Atlante. Sagarion comptant installer ce couple à la tête de Mû puis remplacer le mari afin de poursuivre les négociations avec les atlantes, hélas, Kelrana ne propose personne qui existe. Son plus gros défi est de gérer l’existence de Kalira Athegos, la vraie reine légitime de tous les Aseryns. C’est lui qui avait fait tuer la descendance de Kyriak son petit-fils John Silver. Il sert la princesse Deidea Eina Zenos, son amante et marionnette dans ses complots."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
export default PAYLOAD;
